import{_ as a,I as e,o as n,c as s,b6 as d,J as i}from"./chunks/framework.COUcLbTA.js";const _=JSON.parse('{"title":"从单体到微服务的演进","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/appendix/6-architecture-and-system-design/monolith-to-microservices.md","filePath":"zh-cn/appendix/6-architecture-and-system-design/monolith-to-microservices.md"}'),l={name:"zh-cn/appendix/6-architecture-and-system-design/monolith-to-microservices.md"};function o(h,t,p,c,g,b){const r=e("ArchEvolutionDemo");return n(),s("div",null,[t[0]||(t[0]=d('<h1 id="从单体到微服务的演进" tabindex="-1">从单体到微服务的演进 <a class="header-anchor" href="#从单体到微服务的演进" aria-label="Permalink to “从单体到微服务的演进”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">前言</p><p><strong>没有哪个架构是&quot;最好的&quot;，只有&quot;最适合当前阶段的&quot;。</strong> 从单体到微服务不是一步到位的跳跃，而是随着业务规模和团队规模增长，逐步演进的过程。过早拆分微服务和过晚拆分一样危险。</p></div><p><strong>这篇文章会带你学什么？</strong></p><p>学完这章后，你将获得：</p><ul><li><strong>演进路径</strong>：理解从单体到微服务的四个阶段</li><li><strong>拆分时机</strong>：知道什么时候该拆、什么时候不该拆</li><li><strong>拆分策略</strong>：掌握按业务域拆分的方法论</li><li><strong>通信模式</strong>：了解服务间同步和异步通信的选择</li><li><strong>数据拆分</strong>：理解数据库拆分的挑战和方案</li></ul><table tabindex="0"><thead><tr><th>章节</th><th>内容</th><th>核心概念</th></tr></thead><tbody><tr><td><strong>第 1 章</strong></td><td>架构演进路径</td><td>单体→模块化→SOA→微服务</td></tr><tr><td><strong>第 2 章</strong></td><td>拆分时机与原则</td><td>Conway 定律、团队自治</td></tr><tr><td><strong>第 3 章</strong></td><td>拆分策略</td><td>DDD 限界上下文、绞杀者模式</td></tr><tr><td><strong>第 4 章</strong></td><td>服务通信</td><td>REST、gRPC、消息队列</td></tr><tr><td><strong>第 5 章</strong></td><td>数据拆分</td><td>数据库拆分、数据同步</td></tr></tbody></table><hr><h2 id="_1-架构演进路径" tabindex="-1">1. 架构演进路径 <a class="header-anchor" href="#_1-架构演进路径" aria-label="Permalink to “1. 架构演进路径”">​</a></h2><p>架构演进不是技术驱动的，而是<strong>组织规模驱动的</strong>。当团队从 5 人增长到 500 人时，单体架构的协作效率会急剧下降。</p><table tabindex="0"><thead><tr><th>阶段</th><th>架构</th><th>团队规模</th><th>特点</th></tr></thead><tbody><tr><td>起步期</td><td>单体应用</td><td>1~10 人</td><td>所有代码在一个项目中，部署简单</td></tr><tr><td>成长期</td><td>模块化单体</td><td>10~50 人</td><td>代码按模块划分，但仍然一起部署</td></tr><tr><td>扩张期</td><td>SOA（面向服务）</td><td>50~200 人</td><td>按业务线拆分为粗粒度服务</td></tr><tr><td>规模期</td><td>微服务</td><td>200+ 人</td><td>细粒度服务，每个团队独立开发部署</td></tr></tbody></table>',10)),i(r),t[1]||(t[1]=d(`<div class="tip custom-block"><p class="custom-block-title">Conway 定律</p><p>&quot;设计系统的组织，其产生的架构等同于组织的沟通结构。&quot;——Melvin Conway</p><p>简单说：3 个团队做一个系统，最终会变成 3 个服务。架构拆分的本质是<strong>组织拆分</strong>。</p><p><strong>反向 Conway 定律</strong>：既然组织结构决定了系统架构，那么想要什么样的架构，就先调整成什么样的组织结构。比如你想拆出独立的支付服务，就先组建一个独立的支付团队。很多公司微服务拆分失败，不是技术问题，而是组织没有跟着调整。</p></div><hr><h2 id="_2-什么时候该拆微服务" tabindex="-1">2. 什么时候该拆微服务？ <a class="header-anchor" href="#_2-什么时候该拆微服务" aria-label="Permalink to “2. 什么时候该拆微服务？”">​</a></h2><p>不是所有系统都需要微服务。过早拆分会带来不必要的复杂性。</p><table tabindex="0"><thead><tr><th>信号</th><th>说明</th><th>建议</th></tr></thead><tbody><tr><td>部署冲突频繁</td><td>多个团队改同一个代码库，经常冲突</td><td>考虑拆分</td></tr><tr><td>某模块需要独立扩容</td><td>搜索模块需要 10 倍于其他模块的资源</td><td>考虑拆分</td></tr><tr><td>技术栈需要差异化</td><td>AI 模块用 Python，主站用 Java</td><td>考虑拆分</td></tr><tr><td>团队 &lt; 10 人</td><td>沟通成本低，单体足够</td><td>不要拆</td></tr><tr><td>业务还在探索期</td><td>需求变化快，边界不清晰</td><td>不要拆</td></tr><tr><td>没有 DevOps 能力</td><td>没有 CI/CD、容器化、监控体系</td><td>不要拆</td></tr></tbody></table><hr><h2 id="_3-拆分策略" tabindex="-1">3. 拆分策略 <a class="header-anchor" href="#_3-拆分策略" aria-label="Permalink to “3. 拆分策略”">​</a></h2><h3 id="_3-1-按业务域拆分-ddd-限界上下文" tabindex="-1">3.1 按业务域拆分（DDD 限界上下文） <a class="header-anchor" href="#_3-1-按业务域拆分-ddd-限界上下文" aria-label="Permalink to “3.1 按业务域拆分（DDD 限界上下文）”">​</a></h3><p>DDD（领域驱动设计）的限界上下文（Bounded Context）是拆分微服务的最佳指导原则。每个限界上下文对应一个独立的业务域，有自己的数据模型和业务规则。</p><p><strong>什么是限界上下文？</strong> 同一个词在不同业务域中含义不同。比如&quot;用户&quot;在用户域是指注册信息（姓名、邮箱），在订单域是指下单人（收货地址、支付方式），在推荐域是指行为画像（浏览历史、偏好标签）。限界上下文就是划定一个边界，在这个边界内，术语和模型有明确统一的含义。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌─────────────┐  ┌─────────────┐  ┌─────────────┐</span></span>
<span class="line"><span>│   用户域     │  │   订单域     │  │   支付域     │</span></span>
<span class="line"><span>│             │  │             │  │             │</span></span>
<span class="line"><span>│ User        │  │ Order       │  │ Payment     │</span></span>
<span class="line"><span>│ Profile     │  │ OrderItem   │  │ Refund      │</span></span>
<span class="line"><span>│ Address     │  │ Cart        │  │ Transaction │</span></span>
<span class="line"><span>│             │  │             │  │             │</span></span>
<span class="line"><span>│ 用户服务    │  │ 订单服务     │  │ 支付服务    │</span></span>
<span class="line"><span>└──────┬──────┘  └──────┬──────┘  └──────┬──────┘</span></span>
<span class="line"><span>       │                │                │</span></span>
<span class="line"><span>       └────── API 调用 / 事件通信 ───────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>限界上下文</th><th>核心实体</th><th>对应服务</th></tr></thead><tbody><tr><td>用户域</td><td>User、Profile、Address</td><td>用户服务</td></tr><tr><td>商品域</td><td>Product、Category、SKU</td><td>商品服务</td></tr><tr><td>订单域</td><td>Order、OrderItem</td><td>订单服务</td></tr><tr><td>支付域</td><td>Payment、Refund</td><td>支付服务</td></tr><tr><td>物流域</td><td>Shipment、Tracking</td><td>物流服务</td></tr></tbody></table><h3 id="_3-2-绞杀者模式-strangler-fig-pattern" tabindex="-1">3.2 绞杀者模式（Strangler Fig Pattern） <a class="header-anchor" href="#_3-2-绞杀者模式-strangler-fig-pattern" aria-label="Permalink to “3.2 绞杀者模式（Strangler Fig Pattern）”">​</a></h3><p>不要一次性重写整个单体，而是像绞杀榕一样，逐步用新服务替换旧模块：</p><ol><li>在单体外部创建新服务</li><li>通过代理层将部分流量路由到新服务</li><li>验证新服务稳定后，逐步迁移更多流量</li><li>最终完全替换旧模块</li></ol><hr><h2 id="_4-服务通信模式" tabindex="-1">4. 服务通信模式 <a class="header-anchor" href="#_4-服务通信模式" aria-label="Permalink to “4. 服务通信模式”">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>协议</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td>REST</td><td>HTTP/JSON</td><td>简单通用，生态好</td><td>对外 API、CRUD 操作</td></tr><tr><td>gRPC</td><td>HTTP/2 + Protobuf</td><td>高性能，强类型</td><td>内部服务间高频调用</td></tr><tr><td>消息队列</td><td>AMQP/Kafka</td><td>异步解耦，削峰填谷</td><td>事件通知、异步任务</td></tr><tr><td>GraphQL</td><td>HTTP/JSON</td><td>客户端按需查询</td><td>BFF 层、移动端</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">同步 vs 异步的选择</p><ul><li><strong>需要立即返回结果</strong> → 同步（REST/gRPC）</li><li><strong>不需要立即返回</strong> → 异步（消息队列）</li><li><strong>一个事件触发多个动作</strong> → 异步（发布-订阅）</li></ul><p>经验法则：能异步就异步，同步调用链越长，系统越脆弱。</p></div><hr><h2 id="_5-数据拆分-最难的部分" tabindex="-1">5. 数据拆分：最难的部分 <a class="header-anchor" href="#_5-数据拆分-最难的部分" aria-label="Permalink to “5. 数据拆分：最难的部分”">​</a></h2><p>微服务拆分中最痛苦的不是代码拆分，而是数据库拆分。每个服务应该拥有自己的数据库，但这意味着跨服务查询变得困难。</p><table tabindex="0"><thead><tr><th>挑战</th><th>描述</th><th>解决方案</th></tr></thead><tbody><tr><td>跨服务 JOIN</td><td>不能直接 JOIN 两个服务的表</td><td>API 组合查询、数据冗余</td></tr><tr><td>分布式事务</td><td>跨库事务无法用本地事务</td><td>Saga、本地消息表</td></tr><tr><td>数据一致性</td><td>多个服务的数据可能暂时不一致</td><td>最终一致性、事件驱动</td></tr><tr><td>数据迁移</td><td>从共享库迁移到独立库</td><td>双写过渡、数据同步工具</td></tr></tbody></table><hr><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h2><p>从单体到微服务是一个渐进的过程，不是一蹴而就的革命。</p><p>回顾本章的关键要点：</p><ol><li><strong>演进路径</strong>：单体→模块化单体→SOA→微服务，每一步都有明确的驱动力</li><li><strong>拆分时机</strong>：团队规模、部署冲突、扩容需求是拆分的信号</li><li><strong>拆分策略</strong>：用 DDD 限界上下文指导拆分，用绞杀者模式渐进迁移</li><li><strong>通信选择</strong>：能异步就异步，同步调用链越短越好</li><li><strong>数据拆分</strong>：最难但最重要，接受最终一致性是关键心态转变</li></ol><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to “延伸阅读”">​</a></h2><ul><li><a href="https://www.oreilly.com/library/view/building-microservices-2nd/9781492034018/" target="_blank" rel="noreferrer">Building Microservices</a> - Sam Newman 微服务经典</li><li><a href="https://www.oreilly.com/library/view/monolith-to-microservices/9781492047834/" target="_blank" rel="noreferrer">Monolith to Microservices</a> - 渐进式迁移指南</li><li><a href="https://www.domainlanguage.com/ddd/" target="_blank" rel="noreferrer">Domain-Driven Design</a> - Eric Evans 的 DDD 经典</li><li><a href="https://martinfowler.com/bliki/StranglerFigApplication.html" target="_blank" rel="noreferrer">The Strangler Fig Pattern</a> - Martin Fowler 的绞杀者模式</li></ul>`,30))])}const u=a(l,[["render",o]]);export{_ as __pageData,u as default};
